"use client";
import { FormEvent, KeyboardEvent, useEffect, useRef, useState } from "react";
import { ArrowRightLeft, BarChart3, Bell, Building2, CalendarRange, CarFront, CheckCircle2, ChevronLeft, ChevronRight, CircleDollarSign, Clock3, Copy, KeyRound, LayoutDashboard, LogOut, Mail, ParkingCircle, Pencil, Plus, ScanLine, Search, Settings2, ShieldCheck, TicketCheck, UserPlus, Users, WalletCards, type LucideIcon } from "lucide-react";
import { TicketCodes } from "@/app/components/codes";
import { displayPlate, minutesSince } from "@/app/lib/parking";
import { useParkingStore } from "@/app/hooks/use-parking-store";
import type { AppModule, ParkingStay, Payment } from "@/app/types/parking";

const currency=new Intl.NumberFormat("es-MX",{style:"currency",currency:"MXN",maximumFractionDigits:0});
const clock=new Intl.DateTimeFormat("es-MX",{hour:"2-digit",minute:"2-digit",hour12:false,timeZone:"America/Mexico_City"});
const nav:{id:AppModule;label:string;icon:LucideIcon;group?:string}[]=[
  {id:"dashboard",label:"Resumen",icon:LayoutDashboard},{id:"entries",label:"Entradas y salidas",icon:ArrowRightLeft},
  {id:"shifts",label:"Turnos y caja",icon:WalletCards,group:"GESTIÓN"},{id:"cashCuts",label:"Cortes de caja",icon:CalendarRange},{id:"reports",label:"Reportes",icon:BarChart3},{id:"staff",label:"Personal",icon:Users},
  {id:"settings",label:"Configuración",icon:Settings2,group:"ADMINISTRACIÓN"},
];

function duration(iso:string){const mins=minutesSince(iso);return `${Math.floor(mins/60)?`${Math.floor(mins/60)} h `:""}${mins%60} min`;}
function Brand(){return <div className="brand"><img src="/syntra/logo-wordmark-dark.png" alt="Syntra Software"/><small>PARKFLOW</small></div>}
function Stat({label,value,hint,tone,icon:Icon}:{label:string;value:string;hint:string;tone:string;icon:LucideIcon}){return <article className="stat"><span className={`stat-icon ${tone}`}><Icon size={19}/></span><div><p>{label}</p><strong>{value}</strong><small>{hint}</small></div></article>}

export default function Home(){
  const store=useParkingStore(); const [module,setModule]=useState<AppModule>("dashboard"); const [query,setQuery]=useState(""); const [modal,setModal]=useState<"entry"|"checkout"|"camera"|"ticket"|"cashRegister"|"openShift"|"closeShift"|"login"|null>(null);
  const [plate,setPlate]=useState(""); const [make,setMake]=useState(""); const [model,setModel]=useState(""); const [color,setColor]=useState(""); const [selected,setSelected]=useState<ParkingStay|null>(null); const [method,setMethod]=useState<Payment["method"]>("cash"); const [toast,setToast]=useState(""); const [saving,setSaving]=useState(false);
  const [email,setEmail]=useState(""),[password,setPassword]=useState("");
  const [registerName,setRegisterName]=useState("Caja principal"),[selectedRegisterId,setSelectedRegisterId]=useState(""),[openingCash,setOpeningCash]=useState(0),[countedCash,setCountedCash]=useState(0),[shiftNotes,setShiftNotes]=useState("");
  const [authError,setAuthError]=useState("");
  const [hydrated,setHydrated]=useState(false);
  const [sidebarCollapsed,setSidebarCollapsed]=useState(false);
  const scanInputRef=useRef<HTMLInputElement>(null);
  useEffect(()=>setHydrated(true),[]);
  useEffect(()=>{if((module==="entries"||module==="vehicles")&&!modal){const id=window.setTimeout(()=>scanInputRef.current?.focus(),60);return()=>window.clearTimeout(id)}},[module,modal]);
  useEffect(()=>{if((module==="entries"||module==="vehicles")&&store.authState==="authenticated"&&store.shift.status!=="open"&&!modal){const register=store.cashRegisters.find(r=>r.lotId===store.lotId);setSelectedRegisterId(register?.id??"");setRegisterName(register?.name??"Caja principal");setModal("openShift")}},[module,store.authState,store.shift.status,store.lotId]);
  const dayKey=(iso:string)=>new Intl.DateTimeFormat("en-CA",{timeZone:"America/Mexico_City"}).format(new Date(iso));
  const todayKey=dayKey(new Date().toISOString());
  const dailyStays=store.stays.filter(s=>s.lotId===store.lotId&&(s.status==="active"||s.status==="pending_payment"||dayKey(s.enteredAt)===todayKey));
  const filtered=dailyStays.filter(s=>`${s.plate} ${s.make} ${s.model} ${s.folio} ${s.barcodeValue}`.toLowerCase().includes(query.toLowerCase()));
  const activeFiltered=store.active.filter(s=>`${s.plate} ${s.make} ${s.model} ${s.folio}`.toLowerCase().includes(query.toLowerCase()));
  const visibleStays=filtered;
  const pendingCount=store.active.filter(s=>s.status==="pending_payment").length;
  const shiftPayments=store.payments.filter(p=>store.source==="fallback"?new Date(p.paidAt).toDateString()===new Date().toDateString():p.shiftId===store.shift.id);
  const revenue=shiftPayments.reduce((a,p)=>a+p.amount,store.source==="fallback"?8420:0);
  const cashRevenue=shiftPayments.filter(p=>p.method==="cash").reduce((a,p)=>a+p.amount,store.source==="fallback"?8420:0);
  const occupancy=Math.round(store.active.length/store.lot.capacity*100); const available=store.lot.capacity-store.active.length;
  const currentDate=new Intl.DateTimeFormat("es-MX",{weekday:"long",day:"numeric",month:"long"}).format(new Date());
  function notify(v:string){setToast(v);setTimeout(()=>setToast(""),2600)}
  async function submitEntry(e:FormEvent){e.preventDefault();if(!plate.trim())return;setSaving(true);try{const stay=await store.registerEntry({plate,make,model,color});setSelected(stay);setPlate("");setMake("");setModel("");setColor("");setModal("ticket")}catch(error){notify(error instanceof Error?error.message:"No fue posible registrar la entrada")}finally{setSaving(false)}}
  function openCheckout(stay?:ParkingStay){if(store.shift.status!=="open"||store.shift.lotId!==store.lotId){notify("Debes abrir una caja antes de registrar cobros");setModule("shifts");setModal("openShift");return}setSelected(stay??store.active.find(s=>s.status==="pending_payment")??store.active[0]??null);setModal("checkout")}
  function findScannedStay(value:string){const code=value.trim().toLowerCase();return store.active.find(s=>[s.barcodeValue,s.qrToken,s.folio,s.plate].some(candidate=>candidate.toLowerCase()===code)||s.qrToken.toLowerCase().endsWith(code))}
  function processScan(value:string){const stay=findScannedStay(value);if(stay){setQuery("");openCheckout(stay)}else notify("No encontramos un boleto activo con ese código")}
  function handleScanKey(e:KeyboardEvent<HTMLInputElement>){if(e.key!=="Enter")return;e.preventDefault();if(query.trim())processScan(query)}
  async function pay(){if(!selected)return;setSaving(true);try{const amount=await store.charge(selected,method);setModal(null);notify(`Salida registrada · ${currency.format(amount)}`)}catch(error){notify(error instanceof Error?error.message:"No fue posible registrar el cobro")}finally{setSaving(false)}}
  async function submitOpenShift(e:FormEvent){e.preventDefault();setSaving(true);try{const register=store.cashRegisters.find(r=>r.id===selectedRegisterId)??store.cashRegisters.find(r=>r.lotId===store.lotId);await store.openShift({registerId:register?.id,registerName:register?.name??registerName,openingCash});setModal(null);notify("Caja abierta correctamente")}catch(error){notify(error instanceof Error?error.message:"No fue posible abrir la caja")}finally{setSaving(false)}}
  async function submitCashRegister(e:FormEvent){e.preventDefault();setSaving(true);try{await store.createCashRegister({name:registerName});setModal(null);notify("Nueva caja creada correctamente")}catch(error){notify(error instanceof Error?error.message:"No fue posible crear la caja")}finally{setSaving(false)}}
  async function submitCloseShift(e:FormEvent){e.preventDefault();setSaving(true);try{await store.closeShift({countedCash,expectedCash:cashRevenue+store.shift.openingCash,notes:shiftNotes});setModal(null);setShiftNotes("");notify("Turno cerrado correctamente")}catch(error){notify(error instanceof Error?error.message:"No fue posible cerrar el turno")}finally{setSaving(false)}}
  async function login(e:FormEvent){e.preventDefault();setSaving(true);setAuthError("");try{await store.signIn(email,password);setModal(null);setPassword("");notify("Supabase conectado correctamente")}catch(error){setAuthError(error instanceof Error?error.message:"No fue posible iniciar sesión")}finally{setSaving(false)}}
  async function registerBusiness(input:{name:string;slug:string;lotName:string;lotCode:string;capacity:number;ownerName:string;ownerEmail:string;ownerPassword:string}){setSaving(true);setAuthError("");try{await store.registerBusiness(input);setPassword("");notify("Empresa creada correctamente")}catch(error){const message=error instanceof Error?error.message:"No fue posible crear la empresa";setAuthError(message);throw error}finally{setSaving(false)}}
  const titles:Record<AppModule,[string,string]>={dashboard:["Resumen","Panorama operativo en tiempo real"],entries:["Entradas y salidas","Control de accesos, vehículos y cobros"],vehicles:["Entradas y salidas","Control de accesos, vehículos y cobros"],shifts:["Turnos y caja","Apertura y operación de cajas"],cashCuts:["Cortes de caja","Historial de cierres por usuario"],reports:["Reportes","Indicadores de operación e ingresos"],staff:["Personal","Usuarios, roles y sucursales"],settings:["Configuración","Tarifas, espacios y dispositivos"]};
  if(!hydrated||store.authState==="checking")return <div className="app-loading" role="status" aria-live="polite"><Brand/><span className="loading-ring"/><p>Verificando acceso seguro…</p></div>;
  if(store.authState==="unauthenticated")return <LoginScreen email={email} setEmail={setEmail} password={password} setPassword={setPassword} error={authError||store.syncError} saving={saving} onLogin={login} onRegister={registerBusiness} onDemo={store.continueDemo}/>;
  return <div className={`shell ${sidebarCollapsed?"sidebar-is-collapsed":""}`}>
    <aside className="sidebar"><button className="sidebar-toggle" aria-label={sidebarCollapsed?"Expandir menú":"Contraer menú"} onClick={()=>setSidebarCollapsed(v=>!v)}><ChevronLeft size={14}/></button><Brand/><nav>{nav.filter(item=>store.canManageStaff||item.id!=="staff").map(item=>{const Icon=item.icon;return <div key={item.id}>{item.group&&<p>{item.group}</p>}<button className={module===item.id?"active":""} onClick={()=>setModule(item.id)} title={sidebarCollapsed?item.label:undefined}><span><Icon size={18}/></span><b>{item.label}</b>{item.id==="vehicles"&&<em>{store.active.length}</em>}</button></div>})}</nav><div className="side-profile"><span>{store.businessName.split(" ").map(v=>v[0]).join("").slice(0,2)}</span><div><b>{store.businessName}</b><small>Negocio activo</small></div><footer className={store.shift.status==="open"?"shift-open":"shift-closed"}><i/>{store.shift.status==="open"?"Caja abierta":"Caja cerrada"}<button aria-label="Cerrar sesión" onClick={()=>void store.signOut()}><LogOut size={15}/> <b>Salir</b></button></footer></div></aside>
    <main><header className="topbar"><div className="top-title"><button className="mobile-brand"><Brand/></button><div><h1>{titles[module][0]}</h1><p>{store.businessName} · {titles[module][1]}</p></div></div><div className="top-controls syntra-context"><div className="business-context"><span><Building2 size={16}/></span><div><small>EMPRESA</small><b>{store.businessName}</b></div></div><label className="branch-context"><span><ParkingCircle size={16}/></span><div><small>SUCURSAL ACTIVA</small><select value={store.lotId} disabled={!store.lots.length} onChange={e=>store.setLotId(e.target.value)}>{!store.lots.length&&<option value="">Sin sucursales registradas</option>}{store.lots.filter(l=>store.profile.allowedLotIds.includes(l.id)).map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select></div></label><button className="notification-button" aria-label="Notificaciones"><Bell size={18}/>{pendingCount>0&&<em>{pendingCount>9?"9+":pendingCount}</em>}</button><button className={`online sync-button ${store.source}`} title={store.syncError} onClick={()=>store.source==="fallback"&&setModal("login")}><i/>{store.source==="supabase"?"En línea":store.source==="loading"?"Conectando…":"Conectar"}</button></div></header>

      {module==="dashboard"&&<div className="screen">
        <section className="intro dashboard-intro"><div><p className="eyebrow">PANORAMA DEL ESTACIONAMIENTO</p><h2>Rendimiento general</h2><p>Ocupación, ingresos y operación en un solo lugar.</p></div><div className="dashboard-intro-actions"><span className="date-badge"><Clock3 size={16}/>{currentDate}</span><div className="intro-actions"><button className="secondary" onClick={()=>openCheckout()}>Procesar salida</button><button className="primary" onClick={()=>setModal("entry")}>＋ Registrar entrada</button></div></div></section>
        <section className="stats"><Stat label="Vehículos dentro" value={String(store.active.length)} hint={`${occupancy}% de ocupación`} tone="green" icon={CarFront}/><Stat label="Espacios disponibles" value={String(available)} hint={`de ${store.lot.capacity} totales`} tone="blue" icon={ParkingCircle}/><Stat label="Ingresos del turno" value={currency.format(revenue)} hint="Cobros confirmados" tone="amber" icon={CircleDollarSign}/><Stat label="Tiempo promedio" value="1 h 42 m" hint="por vehículo" tone="violet" icon={Clock3}/></section>
        <section className="dash-grid"><article className="card activity"><div className="card-head"><div><p className="eyebrow">OPERACIÓN EN VIVO</p><h3>Vehículos activos</h3></div><button onClick={()=>setModule("entries")}>Ver todos →</button></div><div className="search"><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar placa, vehículo o folio" aria-label="Buscar vehículos"/></div><StayList stays={activeFiltered.slice(0,5)} onOpen={openCheckout}/></article>
          <aside className="card quick"><div className="card-head"><div><p className="eyebrow">ATAJOS</p><h3>Acciones rápidas</h3></div></div><button onClick={()=>setModal("entry")}><span className="action-icon green">＋</span><div><b>Nueva entrada</b><small>Generar e imprimir boleto</small></div><i>›</i></button><button onClick={()=>openCheckout()}><span className="action-icon blue">⌗</span><div><b>Procesar salida</b><small>Escanear QR o buscar placa</small></div><i>›</i></button><button onClick={()=>setModule("shifts")}><span className="action-icon amber">▣</span><div><b>Corte de caja</b><small>Resumen y cierre de turno</small></div><i>›</i></button><div className="rate-box"><span>Tarifa actual</span><b>{currency.format(store.rate.price)} <small>/ {store.rate.fractionMinutes} min</small></b><button onClick={()=>setModule("settings")}>Editar</button></div></aside></section>
        <section className="system-bar"><div><i/><span><b>Sistema operando correctamente</b><small>Datos guardados y dispositivos listos</small></span></div><p>Impresora <b>● Conectada</b></p><p>Lector QR <b>● Listo</b></p></section>
      </div>}

      {(module==="entries"||module==="vehicles")&&<div className="screen stays-screen"><section className="operation-summary"><article><span className="summary-icon green"><CarFront/></span><div><small>Vehículos activos</small><b>{store.active.length}</b></div><em>{occupancy}% ocupado</em></article><article><span className="summary-icon blue"><ParkingCircle/></span><div><small>Espacios libres</small><b>{available}</b></div><em>de {store.lot.capacity}</em></article><article className={pendingCount?"attention":""}><span className="summary-icon amber"><TicketCheck/></span><div><small>Por cobrar</small><b>{pendingCount}</b></div><em>{pendingCount?"Requiere atención":"Todo al día"}</em></article></section><section className="scan-workspace scan-workspace-inline"><div className="scan-input"><Search size={20}/><input ref={scanInputRef} value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={handleScanKey} onBlur={()=>{if(!modal)window.setTimeout(()=>scanInputRef.current?.focus(),100)}} placeholder="Escanea QR / código de barras o escribe placa, folio, marca…" aria-label="Escanear boleto o buscar vehículo" autoComplete="off" inputMode="search"/><kbd>ENTER</kbd></div><button type="button" className="camera-inline-button" onClick={()=>setModal("camera")}><ScanLine size={19}/><span>Usar cámara</span></button><button type="button" className="primary entry-inline-button" onClick={()=>setModal("entry")}><Plus size={19}/><span>Nueva entrada</span></button><p><i/> Lector conectado y esperando código</p></section><article className="card list-card"><div className="daily-list-heading"><div><h3>Movimientos de hoy</h3></div><div className={`entry-shift-badge ${store.shift.status}`}><i/>{store.shift.status==="open"?`${store.cashRegisters.find(r=>r.id===store.shift.cashRegisterId)?.name??"Caja"} abierta`:"Caja cerrada"}</div><span>{visibleStays.length} {visibleStays.length===1?"vehículo":"vehículos"}</span></div><div className="list-head"><span>Vehículo</span><span>Entrada</span><span>Tiempo</span><span>Estado y acción</span></div><StayList stays={visibleStays} onOpen={openCheckout}/></article></div>}

      {module==="shifts"&&<div className="screen shift-screen">{store.shift.status==="open"?<><section className="intro compact shift-toolbar"><div><span className="shift-status"><i/> Turno abierto</span><p>Abierto por {store.shift.openedBy} a las {clock.format(new Date(store.shift.openedAt))}</p></div><div className="shift-actions"><button className="secondary" onClick={()=>{setRegisterName("");setModal("cashRegister")}}><Plus size={16}/> Nueva caja</button><button className="danger-outline" onClick={()=>{setCountedCash(revenue+store.shift.openingCash);setModal("closeShift")}}>Cerrar turno</button></div></section><section className="stats three"><Stat label="Fondo inicial" value={currency.format(store.shift.openingCash)} hint="Efectivo registrado" tone="blue" icon={WalletCards}/><Stat label="Ventas del turno" value={currency.format(revenue)} hint={`${shiftPayments.length+(store.source==="fallback"?64:0)} operaciones`} tone="green" icon={CircleDollarSign}/><Stat label="Efectivo esperado" value={currency.format(revenue+store.shift.openingCash)} hint="Antes del retiro" tone="amber" icon={Clock3}/></section><article className="card table-card"><div className="card-head"><div><p className="eyebrow">MOVIMIENTOS</p><h3>Pagos recientes</h3></div></div><table><thead><tr><th>Hora</th><th>Folio</th><th>Método</th><th>Importe</th></tr></thead><tbody>{shiftPayments.length?shiftPayments.map(p=><tr key={p.id}><td>{clock.format(new Date(p.paidAt))}</td><td>{store.stays.find(s=>s.id===p.stayId)?.folio}</td><td>{p.method}</td><td><b>{currency.format(p.amount)}</b></td></tr>):<tr><td colSpan={4} className="empty">Los nuevos cobros aparecerán aquí.</td></tr>}</tbody></table></article></>:<section className="card no-shift-state"><span><WalletCards/></span><p className="eyebrow">CAJA CERRADA</p><h2>Abre una caja para comenzar</h2><p>Registra el fondo inicial de la sucursal. Mientras no exista un turno abierto, ParkFlow impedirá procesar cualquier cobro.</p><div className="no-shift-actions"><button className="secondary" onClick={()=>{setRegisterName("");setModal("cashRegister")}}><Plus size={17}/> Nueva caja</button><button className="primary" onClick={()=>{setRegisterName("Caja principal");setModal("openShift")}}><WalletCards size={17}/> Abrir caja</button></div></section>}</div>}

      {module==="shifts"&&<section className="screen register-catalog"><div className="register-catalog-head"><div><p className="eyebrow">PUNTOS DE COBRO</p><h2>Cajas de la sucursal</h2><p>Selecciona una caja disponible para abrir el siguiente turno.</p></div><button className="secondary" onClick={()=>{setRegisterName("");setModal("cashRegister")}}><Plus size={16}/> Nueva caja</button></div><div className="register-grid">{store.cashRegisters.filter(r=>r.lotId===store.lotId).length?store.cashRegisters.filter(r=>r.lotId===store.lotId).map(register=>{const isOpen=store.shift.status==="open"&&store.shift.cashRegisterId===register.id;return <article className={`card register-card ${isOpen?"open":""}`} key={register.id}><span><WalletCards/></span><div><small>{register.code}</small><h3>{register.name}</h3><p>{isOpen?`Turno abierto por ${store.shift.openedBy}`:"Disponible para abrir turno"}</p></div><em><i/>{isOpen?"Abierta":"Disponible"}</em>{!isOpen&&store.shift.status!=="open"&&<button className="secondary" onClick={()=>{setSelectedRegisterId(register.id);setRegisterName(register.name);setModal("openShift")}}>Abrir</button>}</article>}):<article className="card register-empty"><WalletCards/><p>No hay cajas registradas en esta sucursal.</p><button className="primary" onClick={()=>{setRegisterName("");setModal("cashRegister")}}>Crear primera caja</button></article>}</div></section>}
      {module==="cashCuts"&&<CashCuts store={store}/>}
      {module==="reports"&&<Reports revenue={revenue} payments={store.payments.length}/>} 
      {module==="staff"&&<Staff store={store} notify={notify}/>}
      {module==="settings"&&<Settings store={store} notify={notify}/>} 
    </main>

    <nav className="mobile-nav">{nav.slice(0,4).map(item=>{const Icon=item.icon;return <button key={item.id} className={module===item.id?"active":""} onClick={()=>setModule(item.id)}><span><Icon size={18}/></span><small>{item.label.split(" ")[0]}</small></button>})}<button className="scan-fab" onClick={()=>setModal("camera")}><ScanLine size={21}/></button></nav>
    {modal&&<div className="backdrop" onMouseDown={()=>setModal(null)}><section className="modal" role="dialog" aria-modal="true" onMouseDown={e=>e.stopPropagation()}><button className="close" onClick={()=>setModal(null)}>×</button>
      {modal==="entry"&&<form onSubmit={submitEntry}><ModalHeader overline="NUEVA ENTRADA" title="Registra el vehículo" text="Captura la placa y los datos disponibles para generar un boleto único."/><label>Placas<input autoFocus value={plate} onChange={e=>setPlate(displayPlate(e.target.value))} placeholder="ABC-123-A" required/></label><div className="form-grid"><label>Marca<input value={make} onChange={e=>setMake(e.target.value)} placeholder="Ej. Nissan"/></label><label>Modelo<input value={model} onChange={e=>setModel(e.target.value)} placeholder="Ej. Versa"/></label></div><label>Color<input value={color} onChange={e=>setColor(e.target.value)} placeholder="Ej. Gris"/></label><button className="primary full" type="submit" disabled={saving}>{saving?"Guardando…":"Generar boleto →"}</button></form>}
      {modal==="ticket"&&selected&&<div className="ticket-modal"><ModalHeader overline="ENTRADA REGISTRADA" title="Boleto listo" text="Código generado correctamente."/><div className="paper-ticket"><Brand/><h3>{selected.plate}</h3><p>{selected.folio}</p><TicketCodes token={selected.qrToken} barcode={selected.barcodeValue}/><dl><div><dt>Entrada</dt><dd>{clock.format(new Date(selected.enteredAt))}</dd></div><div><dt>Tarifa</dt><dd>{currency.format(store.rate.price)} / {store.rate.fractionMinutes} min</dd></div></dl><small>Conserva este boleto para registrar tu salida.</small></div><button className="primary full" onClick={()=>{notify("Boleto enviado a la impresora térmica");setTimeout(()=>window.print(),300)}}>▣ Imprimir boleto</button></div>}
      {modal==="checkout"&&<div><ModalHeader overline="SALIDA IDENTIFICADA" title="Confirmar cobro" text="Verifica el vehículo y selecciona el método de pago."/><label>Vehículo<select value={selected?.id??""} onChange={e=>setSelected(store.active.find(s=>s.id===e.target.value)??null)}><option value="">Selecciona una placa</option>{store.active.map(s=><option key={s.id} value={s.id}>{s.plate} · {s.folio}</option>)}</select></label>{selected&&<><div className="charge checkout-charge"><span className="vehicle-icon"><CarFront size={19}/></span><div><b>{selected.plate}</b><small>{duration(selected.enteredAt)} · {selected.folio}</small></div><strong>{currency.format(store.calculate(selected))}</strong></div><p className="payment-label">Método de pago</p><div className="methods">{(["cash","card","transfer"] as const).map(m=><button key={m} className={method===m?"active":""} onClick={()=>setMethod(m)}>{m==="cash"?"Efectivo":m==="card"?"Tarjeta":"Transferencia"}</button>)}</div><button className="primary full" onClick={pay} disabled={saving}>{saving?"Procesando…":`Cobrar ${currency.format(store.calculate(selected))}`}</button></>}</div>}
      {modal==="camera"&&<CameraScanner onDetected={value=>{const stay=findScannedStay(value);if(stay)openCheckout(stay);else notify("El código leído no corresponde a una estancia activa")}}/>}
      {modal==="cashRegister"&&<form onSubmit={submitCashRegister} className="shift-form"><ModalHeader overline="NUEVA CAJA" title="Agregar punto de cobro" text={`Crea una caja adicional para ${store.lot.name}.`}/><div className="shift-form-icon"><WalletCards/><div><b>Caja adicional</b><small>Después podrás seleccionarla por su nombre al abrir un turno.</small></div></div><label>Nombre de la caja<input autoFocus value={registerName} onChange={e=>setRegisterName(e.target.value)} placeholder="Ej. Caja salida norte" required/></label><button className="primary full" type="submit" disabled={saving}>{saving?"Creando caja…":"Crear caja"}</button></form>}
      {modal==="openShift"&&<form onSubmit={submitOpenShift} className="shift-form"><ModalHeader overline="APERTURA DE CAJA" title="Abrir nuevo turno" text={`Selecciona la caja y registra el fondo inicial para ${store.lot.name}.`}/><div className="shift-form-icon"><WalletCards/><div><b>Control de cobros</b><small>Todos los pagos quedarán vinculados a este turno.</small></div></div>{store.cashRegisters.filter(r=>r.lotId===store.lotId).length?<label>Caja<select autoFocus value={selectedRegisterId||store.cashRegisters.find(r=>r.lotId===store.lotId)?.id||""} onChange={e=>{const register=store.cashRegisters.find(r=>r.id===e.target.value);setSelectedRegisterId(e.target.value);setRegisterName(register?.name??"")}}>{store.cashRegisters.filter(r=>r.lotId===store.lotId).map(register=><option key={register.id} value={register.id}>{register.name} · {register.code}</option>)}</select><small>¿Necesitas otra? Créala desde “Nueva caja”.</small></label>:<label>Nombre de la primera caja<input autoFocus value={registerName} onChange={e=>setRegisterName(e.target.value)} placeholder="Caja principal" required/></label>}<label>Fondo inicial<div className="input-affix"><span>$</span><input type="number" min="0" step="0.01" value={openingCash} onChange={e=>setOpeningCash(Number(e.target.value))} required/><span>MXN</span></div></label><div className="creation-summary"><CheckCircle2/><p>Al abrir la caja se habilitarán los cobros en esta sucursal.</p></div><button className="primary full" type="submit" disabled={saving}>{saving?"Abriendo caja…":"Abrir caja y comenzar"}</button></form>}
      {modal==="closeShift"&&<form onSubmit={submitCloseShift}><ModalHeader overline="CIERRE DE TURNO" title="Corte de caja" text="Confirma el efectivo contado antes de cerrar."/><label>Efectivo contado<input type="number" min="0" step="0.01" value={countedCash} onChange={e=>setCountedCash(Number(e.target.value))} required/></label><label>Notas del cierre<input value={shiftNotes} onChange={e=>setShiftNotes(e.target.value)} placeholder="Opcional: diferencias, retiros u observaciones"/></label><div className="charge"><div><b>Efectivo esperado</b><small>Fondo + ventas del turno</small></div><strong>{currency.format(revenue+store.shift.openingCash)}</strong></div><div className={`cash-difference ${countedCash-(revenue+store.shift.openingCash)===0?"balanced":"unbalanced"}`}><span>Diferencia</span><b>{currency.format(countedCash-(revenue+store.shift.openingCash))}</b></div><button className="primary full" type="submit" disabled={saving}>{saving?"Cerrando turno…":"Confirmar corte"}</button></form>}
      {modal==="login"&&<form onSubmit={login}><ModalHeader overline="SINCRONIZACIÓN" title="Conectar con Supabase" text="Inicia sesión con un usuario asignado al estacionamiento."/><label>Correo electrónico<input type="email" autoFocus value={email} onChange={e=>setEmail(e.target.value)} placeholder="usuario@empresa.com" required/></label><label>Contraseña<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="••••••••" required/></label><button className="primary full" type="submit" disabled={saving}>{saving?"Conectando…":"Iniciar sesión"}</button></form>}
    </section></div>}
    {toast&&<div className="toast">● {toast}</div>}
  </div>
}

function CameraScanner({onDetected}:{onDetected:(value:string)=>void}){
  const videoRef=useRef<HTMLVideoElement>(null);const [status,setStatus]=useState("Solicitando acceso a la cámara…");const detected=useRef(false);
  useEffect(()=>{let stream:MediaStream|null=null,frame=0,cancelled=false;async function start(){try{if(!navigator.mediaDevices?.getUserMedia)throw new Error("La cámara no está disponible en este navegador");stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}}});if(cancelled){stream.getTracks().forEach(t=>t.stop());return}const video=videoRef.current;if(!video)return;video.srcObject=stream;await video.play();const Detector=(window as unknown as {BarcodeDetector?:new(options:{formats:string[]})=>{detect:(source:HTMLVideoElement)=>Promise<Array<{rawValue:string}> >}}).BarcodeDetector;if(!Detector){setStatus("Tu navegador no admite lectura automática. Usa Chrome/Edge actualizado o la pistola lectora.");return}const detector=new Detector({formats:["qr_code","code_128","code_39","ean_13","ean_8","upc_a","upc_e"]});setStatus("Apunta al QR o código de barras del boleto");const scan=async()=>{if(cancelled||detected.current)return;try{const codes=await detector.detect(video);if(codes[0]?.rawValue){detected.current=true;onDetected(codes[0].rawValue);return}}catch{}frame=requestAnimationFrame(scan)};frame=requestAnimationFrame(scan)}catch(error){setStatus(error instanceof Error?error.message:"No fue posible abrir la cámara")}}void start();return()=>{cancelled=true;cancelAnimationFrame(frame);stream?.getTracks().forEach(t=>t.stop())}},[onDetected]);
  return <div className="camera-scanner"><ModalHeader overline="LECTOR MÓVIL" title="Escanea el boleto" text="Usa la cámara trasera y mantén el código dentro del marco."/><div className="camera-viewport"><video ref={videoRef} playsInline muted/><span/><i/></div><p><ScanLine size={16}/>{status}</p><small>La cámara solo permanece activa mientras esta ventana está abierta.</small></div>
}

function ModalHeader({overline,title,text}:{overline:string;title:string;text:string}){return <header className="modal-head"><p className="eyebrow">{overline}</p><h2>{title}</h2><p>{text}</p></header>}
function StayList({stays,onOpen}:{stays:ParkingStay[];onOpen:(s:ParkingStay)=>void}){return <div className="stay-list">{stays.map(s=>{const completed=s.status==="paid";return <button className={`stay ${completed?"completed":""}`} key={s.id} onClick={()=>!completed&&onOpen(s)} disabled={completed}><span className="vehicle-icon"><CarFront size={19}/></span><div><b>{s.plate}</b><small>{s.make} {s.model} · {s.color} · {s.folio}</small></div><p><small>Entrada</small><b>{clock.format(new Date(s.enteredAt))}</b></p><p><small>{completed?"Salida":"Estancia"}</small><b>{completed&&s.exitedAt?clock.format(new Date(s.exitedAt)):duration(s.enteredAt)}</b></p><span className="stay-state"><em className={s.status==="pending_payment"?"warning":completed?"completed":""}>● {s.status==="pending_payment"?"Por cobrar":completed?"Salida registrada":"Activo"}</em><strong>{s.status==="pending_payment"?"Cobrar":completed?"Completado":"Procesar salida"}</strong></span>{!completed&&<ChevronRight className="row-chevron" size={18}/>}</button>})}{!stays.length&&<div className="empty">No hay movimientos para mostrar.</div>}</div>}
function CashCuts({store}:{store:ReturnType<typeof useParkingStore>}){
  const [period,setPeriod]=useState<"today"|"yesterday"|"7"|"30"|"custom">("today"),[from,setFrom]=useState(""),[to,setTo]=useState("");
  const nowDate=new Date(),startToday=new Date(nowDate.getFullYear(),nowDate.getMonth(),nowDate.getDate());
  let start=startToday,end=new Date(startToday.getTime()+86400000);
  if(period==="yesterday"){start=new Date(startToday.getTime()-86400000);end=startToday}
  if(period==="7")start=new Date(startToday.getTime()-6*86400000);
  if(period==="30")start=new Date(startToday.getTime()-29*86400000);
  if(period==="custom"){if(from)start=new Date(`${from}T00:00:00`);if(to)end=new Date(new Date(`${to}T00:00:00`).getTime()+86400000)}
  const rows=store.cashCuts.filter(c=>c.lotId===store.lotId&&new Date(c.closedAt)>=start&&new Date(c.closedAt)<end);
  const totalExpected=rows.reduce((sum,c)=>sum+c.expectedCash,0),totalCounted=rows.reduce((sum,c)=>sum+c.countedCash,0),difference=totalCounted-totalExpected;
  const dateTime=new Intl.DateTimeFormat("es-MX",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"});
  return <div className="screen cash-cuts-screen"><section className="cash-cut-toolbar"><div className="cut-presets">{[["today","Hoy"],["yesterday","Ayer"],["7","7 días"],["30","30 días"],["custom","Personalizado"]].map(([value,label])=><button key={value} className={period===value?"active":""} onClick={()=>setPeriod(value as typeof period)}>{label}</button>)}</div>{period==="custom"&&<div className="custom-dates"><label>Desde<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>Hasta<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label></div>}</section><section className="stats three"><Stat label="Cortes realizados" value={String(rows.length)} hint="En el periodo seleccionado" tone="blue" icon={CalendarRange}/><Stat label="Efectivo esperado" value={currency.format(totalExpected)} hint="Suma de todos los cortes" tone="green" icon={CircleDollarSign}/><Stat label="Diferencia acumulada" value={currency.format(difference)} hint={difference===0?"Cajas balanceadas":difference>0?"Sobrante acumulado":"Faltante acumulado"} tone="amber" icon={WalletCards}/></section><article className="card table-card cuts-table"><div className="card-head"><div><p className="eyebrow">HISTORIAL DE CIERRES</p><h3>Detalle por usuario</h3></div><span>{rows.length} {rows.length===1?"corte":"cortes"}</span></div><table><thead><tr><th>Fecha de cierre</th><th>Usuario</th><th>Caja</th><th>Duración</th><th>Fondo inicial</th><th>Esperado</th><th>Contado</th><th>Diferencia</th></tr></thead><tbody>{rows.length?rows.map(cut=>{const register=store.cashRegisters.find(r=>r.id===cut.cashRegisterId),diff=cut.countedCash-cut.expectedCash,totalMinutes=Math.max(0,Math.round((new Date(cut.closedAt).getTime()-new Date(cut.openedAt).getTime())/60000));return <tr key={cut.id}><td><b>{dateTime.format(new Date(cut.closedAt))}</b><small className="table-subtitle">Apertura: {dateTime.format(new Date(cut.openedAt))}</small></td><td><b>{cut.closedBy}</b><small className="table-subtitle">Cerró el turno</small></td><td>{register?.name??"Caja"}<small className="table-subtitle">{register?.code??"—"}</small></td><td>{Math.floor(totalMinutes/60)} h {totalMinutes%60} min</td><td>{currency.format(cut.openingCash)}</td><td>{currency.format(cut.expectedCash)}</td><td><b>{currency.format(cut.countedCash)}</b></td><td><em className={`cut-difference ${diff===0?"balanced":diff>0?"surplus":"shortage"}`}>{diff>0?"+":""}{currency.format(diff)}</em></td></tr>}):<tr><td colSpan={8} className="empty">No hay cortes de caja en el periodo seleccionado.</td></tr>}</tbody></table></article></div>
}

function Reports({revenue,payments}:{revenue:number;payments:number}){const bars=[34,47,39,62,55,78,89,70,93,84,68,74];return <div className="screen"><div className="module-actions"><span>Indicadores de la sucursal activa</span><button className="secondary">↓ Exportar Excel</button></div><section className="stats three"><Stat label="Ingresos" value={currency.format(revenue)} hint="+8% vs. turno anterior" tone="green" icon={CircleDollarSign}/><Stat label="Boletos cobrados" value={String(payments+64)} hint="Operaciones completadas" tone="blue" icon={TicketCheck}/><Stat label="Ocupación máxima" value="72%" hint="Registrada a las 12:40" tone="violet" icon={ParkingCircle}/></section><article className="card chart"><div className="card-head"><div><p className="eyebrow">HOY POR HORA</p><h3>Comportamiento de ingresos</h3></div><b>{currency.format(revenue)}</b></div><div className="bars">{bars.map((v,i)=><div key={i}><span style={{height:`${v}%`}}/><small>{7+i}:00</small></div>)}</div></article></div>}

function PlatformAdminPanel({store,notify}:{store:ReturnType<typeof useParkingStore>;notify:(v:string)=>void}){
  const [open,setOpen]=useState(false),[step,setStep]=useState(1),[saving,setSaving]=useState(false);
  const [name,setName]=useState(""),[slug,setSlug]=useState(""),[lotName,setLotName]=useState(""),[lotCode,setLotCode]=useState(""),[capacity,setCapacity]=useState(100);
  const [ownerName,setOwnerName]=useState(""),[ownerEmail,setOwnerEmail]=useState(""),[ownerPassword,setOwnerPassword]=useState(""),[confirmPassword,setConfirmPassword]=useState("");
  const businesses=Array.from(new Map(store.lots.map(l=>[l.businessId,l])).values());
  function close(){setOpen(false);setStep(1)}
  async function create(e:FormEvent){e.preventDefault();if(ownerPassword!==confirmPassword){notify("Las contraseñas no coinciden");return}setSaving(true);try{await store.createBusiness({name,slug,lotName,lotCode,capacity,ownerName,ownerEmail,ownerPassword});close();notify("Empresa y propietario creados correctamente")}catch(error){notify(error instanceof Error?error.message:"No fue posible crear la empresa")}finally{setSaving(false)}}
  return <div className="screen platform-screen">
    <section className="intro compact"><div><p className="eyebrow">CLIENTES DE LA PLATAFORMA</p><h2>Empresas</h2><p>Da de alta cada empresa junto con su sucursal inicial y usuario responsable.</p></div><button className="primary" onClick={()=>setOpen(true)}><Plus size={17}/> Nueva empresa</button></section>
    <section className="platform-stats"><article><Building2/><div><small>Empresas registradas</small><b>{businesses.length}</b></div></article><article><ParkingCircle/><div><small>Sucursales activas</small><b>{store.lots.length}</b></div></article><article><ShieldCheck/><div><small>Modelo de acceso</small><b>Administrado por cliente</b></div></article></section>
    {businesses.length?<section className="business-cards">{businesses.map(b=><article className="card" key={b.businessId}><span><Building2/></span><div><small>EMPRESA CLIENTE</small><h3>{b.name.replace(/Sucursal|Estacionamiento/gi,"").trim()||b.name}</h3><p>{store.lots.filter(l=>l.businessId===b.businessId).length} sucursal(es) · {store.lots.filter(l=>l.businessId===b.businessId).reduce((a,l)=>a+l.capacity,0)} espacios</p></div><button>Administrar <ChevronRight size={16}/></button></article>)}</section>:<section className="card platform-empty"><span><Building2/></span><h3>Aún no hay empresas registradas</h3><p>Crea el primer cliente junto con su cuenta de propietario y contraseña de acceso.</p><button className="primary" onClick={()=>setOpen(true)}>Crear primera empresa</button></section>}
    {open&&<div className="backdrop" onMouseDown={close}><section className="modal business-wizard" role="dialog" aria-modal="true" onMouseDown={e=>e.stopPropagation()}><button className="close" onClick={close}>×</button><header><p className="eyebrow">ALTA DE CLIENTE</p><h2>Nueva empresa</h2><p>La empresa, sucursal y propietario se crearán en una sola operación.</p></header><div className="wizard-progress">{[[1,"Empresa"],[2,"Sucursal"],[3,"Propietario"]].map(([n,label])=><div key={n} className={step>=Number(n)?"active":""}><span>{step>Number(n)?<CheckCircle2/>:n}</span><b>{label}</b></div>)}</div><form onSubmit={create}>
      {step===1&&<div className="wizard-section"><div className="section-heading"><span><Building2/></span><div><h3>Información de la empresa</h3><p>Datos del cliente que contratará ParkFlow.</p></div></div><label>Nombre comercial<input autoFocus value={name} onChange={e=>{const value=e.target.value;setName(value);setSlug(value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,""))}} placeholder="Ej. Estacionamientos del Centro" required/></label><label>Identificador del sistema<input value={slug} onChange={e=>setSlug(e.target.value)} placeholder="estacionamientos-del-centro" required/><small>Se utiliza internamente para identificar al negocio.</small></label></div>}
      {step===2&&<div className="wizard-section"><div className="section-heading"><span><ParkingCircle/></span><div><h3>Primera sucursal</h3><p>El propietario podrá crear más sucursales posteriormente.</p></div></div><div className="form-grid"><label>Nombre de sucursal<input autoFocus value={lotName} onChange={e=>setLotName(e.target.value)} placeholder="Sucursal Centro" required/></label><label>Código<input value={lotCode} onChange={e=>setLotCode(e.target.value.toUpperCase())} placeholder="CTR" maxLength={8} required/></label></div><label>Capacidad total<input type="number" min={1} value={capacity} onChange={e=>setCapacity(Number(e.target.value))} required/><small>Número de espacios disponibles en esta ubicación.</small></label></div>}
      {step===3&&<div className="wizard-section"><div className="section-heading"><span><ShieldCheck/></span><div><h3>Propietario de la empresa</h3><p>Su cuenta quedará activa de inmediato y podrá iniciar sesión con su contraseña.</p></div></div><div className="owner-role-card"><ShieldCheck/><span><b>Propietario</b><small>Control completo del negocio, sucursales y usuarios.</small></span></div><div className="form-grid"><label>Nombre completo<input autoFocus value={ownerName} onChange={e=>setOwnerName(e.target.value)} placeholder="Nombre del propietario" autoComplete="name" required/></label><label>Correo electrónico<input type="email" value={ownerEmail} onChange={e=>setOwnerEmail(e.target.value)} placeholder="propietario@empresa.com" autoComplete="email" required/></label><label>Contraseña<input type="password" value={ownerPassword} onChange={e=>setOwnerPassword(e.target.value)} placeholder="Mínimo 8 caracteres" minLength={8} autoComplete="new-password" required/><small>Será su contraseña para ingresar a ParkFlow.</small></label><label>Confirmar contraseña<input type="password" value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} placeholder="Repite la contraseña" minLength={8} autoComplete="new-password" required/>{confirmPassword&&ownerPassword!==confirmPassword&&<small className="field-error">Las contraseñas no coinciden.</small>}</label></div><div className="creation-summary"><CheckCircle2/><p>Se crearán la empresa, la primera sucursal, la caja principal, la tarifa inicial y la cuenta confirmada del propietario. No se enviará un enlace mágico.</p></div></div>}
      <footer><button type="button" className="secondary" onClick={step===1?close:()=>setStep(v=>v-1)}>{step===1?"Cancelar":"Anterior"}</button>{step<3?<button type="button" className="primary" onClick={()=>setStep(v=>v+1)}>Continuar</button>:<button className="primary" disabled={saving||ownerPassword!==confirmPassword}>{saving?"Creando empresa…":"Crear empresa y propietario"}</button>}</footer>
    </form></section></div>}
  </div>
}
function SuperAdminPanel({store,notify}:{store:ReturnType<typeof useParkingStore>;notify:(v:string)=>void}){const [open,setOpen]=useState(false),[name,setName]=useState(""),[slug,setSlug]=useState(""),[lotName,setLotName]=useState(""),[lotCode,setLotCode]=useState(""),[capacity,setCapacity]=useState(100),[saving,setSaving]=useState(false);async function create(e:FormEvent){e.preventDefault();setSaving(true);try{await store.createBusiness({name,slug,lotName,lotCode,capacity});setOpen(false);setName("");notify("Negocio y sucursal inicial creados correctamente")}catch(error){notify(error instanceof Error?error.message:"No fue posible crear el negocio")}finally{setSaving(false)}}return <><div className="screen super-admin-head"><section className="intro compact"><div><p className="eyebrow">CONTROL DE PLATAFORMA</p><h2>Super administración</h2><p>Crea negocios, sucursales, dueños y administradores desde un solo lugar.</p></div><button className="primary" onClick={()=>setOpen(v=>!v)}><Plus size={17}/> Nuevo negocio</button></section>{open&&<article className="card inline-form business-form"><div><p className="eyebrow">ALTA DE NEGOCIO</p><h3>Configura la empresa y su primera sucursal</h3></div><form onSubmit={create}><label>Nombre del negocio<input value={name} onChange={e=>{setName(e.target.value);setSlug(e.target.value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,""))}} required/></label><label>Identificador<input value={slug} onChange={e=>setSlug(e.target.value)} placeholder="estacionamiento-centro" required/></label><label>Primera sucursal<input value={lotName} onChange={e=>setLotName(e.target.value)} placeholder="Sucursal Centro" required/></label><label>Código<input value={lotCode} onChange={e=>setLotCode(e.target.value.toUpperCase())} placeholder="CTR" maxLength={8} required/></label><label>Capacidad<input type="number" min={1} value={capacity} onChange={e=>setCapacity(Number(e.target.value))} required/></label><div><button type="button" className="secondary" onClick={()=>setOpen(false)}>Cancelar</button><button className="primary" disabled={saving}>{saving?"Creando…":"Crear negocio"}</button></div></form></article>}<section className="access-summary"><article><ShieldCheck/><div><small>Nivel de acceso</small><b>Control total</b></div></article><article><ParkingCircle/><div><small>Sucursales registradas</small><b>{store.lots.length}</b></div></article><article><Users/><div><small>Usuarios visibles</small><b>{store.staff.length}</b></div></article></section></div><Staff store={store} notify={notify}/></>}
function Staff({store,notify}:{store:ReturnType<typeof useParkingStore>;notify:(v:string)=>void}){
  const [adding,setAdding]=useState(false),[name,setName]=useState(""),[email,setEmail]=useState(""),[role,setRole]=useState("operator"),[lotId,setLotId]=useState(store.lotId),[saving,setSaving]=useState(false);
  const [editingId,setEditingId]=useState<string|null>(null),[active,setActive]=useState(true);
  const [newPassword,setNewPassword]=useState(""),[confirmNewPassword,setConfirmNewPassword]=useState("");
  const [credentials,setCredentials]=useState<{name:string;email:string;password:string}|null>(null);
  const allowedRoles=store.profile.role==="super_admin"?["owner","admin","cashier","operator","viewer"]:store.profile.role==="owner"?["admin","cashier","operator","viewer"]:["cashier","operator","viewer"];
  const availableLots=store.lots.filter(l=>store.profile.allowedLotIds.includes(l.id));
  function close(){if(saving)return;setAdding(false);setEditingId(null);setCredentials(null)}
  function openCreate(){setName("");setEmail("");setRole("operator");setLotId(availableLots[0]?.id??store.lotId);setActive(true);setEditingId(null);setNewPassword("");setConfirmNewPassword("");setCredentials(null);setAdding(true)}
  function openEdit(user:(typeof store.staff)[number]){setName(user.fullName);setEmail(user.email==="Usuario registrado"?"":user.email);setRole(user.role);setLotId(user.lotIds[0]??availableLots[0]?.id??store.lotId);setActive(user.status==="active");setEditingId(user.id);setNewPassword("");setConfirmNewPassword("");setCredentials(null);setAdding(true)}
  function generateNewPassword(){const chars="ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%";const bytes=crypto.getRandomValues(new Uint8Array(14));const password=Array.from(bytes,b=>chars[b%chars.length]).join("");setNewPassword(password);setConfirmNewPassword(password)}
  async function add(e:FormEvent){
    e.preventDefault();setSaving(true);
    try{
      if(editingId){if(newPassword&&newPassword.length<8)throw new Error("La nueva contraseña debe tener al menos 8 caracteres");if(newPassword!==confirmNewPassword)throw new Error("Las contraseñas no coinciden");await store.updateStaff({id:editingId,fullName:name.trim(),email:email.trim()||undefined,role,lotIds:[lotId],active,newPassword:newPassword||undefined});close();notify(newPassword?"Usuario y contraseña actualizados":"Usuario actualizado correctamente");return}
      const created=await store.inviteStaff({fullName:name.trim(),email:email.trim(),role,lotIds:[lotId]});
      setCredentials({name:created.fullName,email:created.email,password:created.temporaryPassword});
      setName("");setEmail("");
      notify("Usuario creado y activado correctamente");
    }catch(error){notify(error instanceof Error?error.message:"No fue posible crear el usuario")}
    finally{setSaving(false)}
  }
  async function copyCredentials(){
    if(!credentials)return;
    try{await navigator.clipboard.writeText(`Usuario: ${credentials.email}\nContraseña temporal: ${credentials.password}`);notify("Credenciales copiadas")}
    catch{notify("No fue posible copiar; selecciona la contraseña manualmente")}
  }
  return <div className="screen">
    <section className="intro compact"><div><p className="eyebrow">CONTROL DE ACCESO</p><h2>{store.profile.role==="super_admin"?"Administradores y usuarios":"Personal y permisos"}</h2><p>{store.profile.role==="super_admin"?"Control global de propietarios, administradores y sucursales.":"Los usuarios solo pueden operar las sucursales que les asignes."}</p></div><button className="primary" onClick={openCreate}><UserPlus size={17}/> Nuevo usuario</button></section>
    <section className="access-summary"><article><ShieldCheck/><div><small>Tu nivel de acceso</small><b>{roleLabel(store.profile.role)}</b></div></article><article><Users/><div><small>Usuarios visibles</small><b>{store.staff.length}</b></div></article><article><ParkingCircle/><div><small>Sucursales administrables</small><b>{store.profile.allowedLotIds.length}</b></div></article></section>
    <article className="card table-card"><table><thead><tr><th>Usuario</th><th>Rol</th><th>Sucursal</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{store.staff.length?store.staff.map(r=><tr key={r.id}><td><b>{r.fullName}</b><small className="table-subtitle">{r.email}</small></td><td>{roleLabel(r.role)}</td><td>{r.lotIds.map(id=>store.lots.find(l=>l.id===id)?.name??id).join(" · ")}</td><td><em className={`status-pill ${r.status!=="active"?"pending":""}`}>● {r.status==="invited"?"Invitado":r.status==="inactive"?"Inactivo":"Activo"}</em></td><td>{r.role!=="owner"&&!(store.profile.role==="admin"&&r.role==="admin")&&<button type="button" className="table-action" onClick={()=>openEdit(r)}><Pencil size={14}/> Editar</button>}</td></tr>):<tr><td colSpan={5} className="empty">Aún no hay usuarios para mostrar.</td></tr>}</tbody></table></article>
    {adding&&<div className="backdrop" onMouseDown={close}><section className="modal staff-modal" role="dialog" aria-modal="true" aria-labelledby="staff-modal-title" onMouseDown={e=>e.stopPropagation()}><button className="close" onClick={close} aria-label="Cerrar">×</button>{credentials?<div className="credential-success"><span className="credential-success-icon"><CheckCircle2/></span><p className="eyebrow">USUARIO CREADO</p><h2 id="staff-modal-title">Acceso listo</h2><p>{credentials.name} ya puede iniciar sesión. Comparte estas credenciales de forma segura.</p><div className="credential-box"><label>Correo electrónico<strong>{credentials.email}</strong></label><label>Contraseña temporal<strong className="temporary-password">{credentials.password}</strong></label><button type="button" className="secondary copy-credentials" onClick={copyCredentials}><Copy size={16}/> Copiar credenciales</button></div><div className="credential-warning"><KeyRound size={18}/><p>Esta contraseña se muestra una sola vez. El usuario deberá cambiarla al iniciar sesión.</p></div><button type="button" className="primary full" onClick={close}>Finalizar</button></div>:<><ModalHeader overline={editingId?"EDITAR USUARIO":"NUEVO USUARIO"} title={editingId?"Actualizar acceso":"Crear acceso"} text={editingId?"Modifica los datos, permisos y estado del colaborador.":"Asigna el rol y la sucursal. ParkFlow generará una contraseña temporal segura."}/><form onSubmit={add} className="staff-modal-form"><div className="staff-modal-grid"><label>Nombre completo<input autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder="Nombre del colaborador" autoComplete="name" required/></label><label>Correo electrónico<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder={editingId?"Déjalo vacío para conservarlo":"usuario@empresa.com"} autoComplete="email" required={!editingId}/></label><label>Rol<select value={role} onChange={e=>setRole(e.target.value)}>{allowedRoles.map(r=><option key={r} value={r}>{roleLabel(r)}</option>)}</select></label><label>Sucursal<select value={lotId} onChange={e=>setLotId(e.target.value)} required>{availableLots.map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select></label>{editingId&&<label>Estado<select value={active?"active":"inactive"} onChange={e=>setActive(e.target.value==="active")}><option value="active">Activo</option><option value="inactive">Inactivo</option></select></label>}</div>{editingId&&<section className="password-reset"><header><span><KeyRound size={18}/></span><div><b>Restablecer contraseña</b><small>Úsalo solamente cuando el colaborador no recuerde su acceso.</small></div><button type="button" className="secondary" onClick={generateNewPassword}>Generar segura</button></header><div className="staff-modal-grid"><label>Nueva contraseña<input type="text" value={newPassword} onChange={e=>setNewPassword(e.target.value)} placeholder="Mínimo 8 caracteres" minLength={8} autoComplete="new-password"/></label><label>Confirmar contraseña<input type="text" value={confirmNewPassword} onChange={e=>setConfirmNewPassword(e.target.value)} placeholder="Repite la contraseña" minLength={8} autoComplete="new-password"/>{confirmNewPassword&&newPassword!==confirmNewPassword&&<small className="field-error">Las contraseñas no coinciden.</small>}</label></div></section>}{!editingId&&<div className="password-notice"><KeyRound size={18}/><div><b>Contraseña generada automáticamente</b><small>La cuenta quedará confirmada y activa, sin enlace mágico.</small></div></div>}<footer className="staff-modal-footer"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" type="submit" disabled={saving||!availableLots.length||Boolean(newPassword&&newPassword!==confirmNewPassword)}>{saving?"Guardando…":editingId?"Guardar cambios":"Crear usuario"}</button></footer></form></>}</section></div>}
  </div>
}
function Settings({store,notify}:{store:ReturnType<typeof useParkingStore>;notify:(v:string)=>void}){const [saving,setSaving]=useState(false);async function save(){setSaving(true);try{await store.saveRate(store.rate);notify(store.source==="supabase"?"Tarifa guardada en Supabase":"Tarifa guardada en respaldo local")}catch(error){notify(error instanceof Error?error.message:"No fue posible guardar la tarifa")}finally{setSaving(false)}}return <div className="screen"><section className="settings-grid"><article className="card settings"><h3>Tarifa general</h3><label>Precio por fracción<div className="input-affix"><span>$</span><input type="number" value={store.rate.price} onChange={e=>store.setRate({...store.rate,price:Number(e.target.value)})}/><span>MXN</span></div></label><label>Duración de la fracción<select value={store.rate.fractionMinutes} onChange={e=>store.setRate({...store.rate,fractionMinutes:Number(e.target.value) as 15|30|45|60})}><option value="15">15 minutos</option><option value="30">30 minutos</option><option value="45">45 minutos</option><option value="60">1 hora</option></select></label><div className="rate-examples">{[15,30,45,60].map(m=><p key={m}><span>{m===60?"1 hora":`${m} minutos`}</span><b>{currency.format(Math.ceil(m/store.rate.fractionMinutes)*store.rate.price)}</b></p>)}</div><button className="primary full" disabled={saving} onClick={save}>{saving?"Guardando…":"Guardar cambios"}</button></article><article className="card settings"><h3>Dispositivos</h3><div className="device"><span>▣</span><div><b>Impresora térmica</b><small>EPSON TM-T20III · USB</small></div><em>● Conectada</em></div><div className="device"><span>⌗</span><div><b>Cámara / lector QR</b><small>Dispositivo móvil</small></div><em>● Listo</em></div><div className="device"><span>▤</span><div><b>Cajón de dinero</b><small>Apertura por impresora</small></div><em>● Disponible</em></div></article></section></div>}

function LoginScreen({email,setEmail,password,setPassword,error,saving,onLogin,onRegister,onDemo}:{email:string;setEmail:(v:string)=>void;password:string;setPassword:(v:string)=>void;error:string;saving:boolean;onLogin:(e:FormEvent)=>void;onRegister:(input:{name:string;slug:string;lotName:string;lotCode:string;capacity:number;ownerName:string;ownerEmail:string;ownerPassword:string})=>Promise<void>;onDemo:()=>void}){
  const [registering,setRegistering]=useState(false),[step,setStep]=useState(1),[forgot,setForgot]=useState(false),[formError,setFormError]=useState("");
  const [name,setName]=useState(""),[slug,setSlug]=useState(""),[lotName,setLotName]=useState("Sucursal principal"),[lotCode,setLotCode]=useState("MATRIZ"),[capacity,setCapacity]=useState(100);
  const [ownerName,setOwnerName]=useState(""),[ownerEmail,setOwnerEmail]=useState(""),[ownerPassword,setOwnerPassword]=useState(""),[confirmPassword,setConfirmPassword]=useState("");
  function back(){if(step>1)setStep(v=>v-1);else{setRegistering(false);setFormError("")}}
  function next(){setFormError("");if(step===1&&(!name.trim()||!slug.trim()))return setFormError("Completa el nombre de la empresa.");if(step===2&&(!lotName.trim()||!lotCode.trim()||capacity<1))return setFormError("Completa los datos de la primera sucursal.");setStep(v=>Math.min(3,v+1))}
  async function create(e:FormEvent){e.preventDefault();setFormError("");if(!ownerName.trim()||!ownerEmail.trim())return setFormError("Completa los datos del propietario.");if(ownerPassword.length<8)return setFormError("La contraseña debe tener al menos 8 caracteres.");if(ownerPassword!==confirmPassword)return setFormError("Las contraseñas no coinciden.");try{await onRegister({name,slug,lotName,lotCode,capacity,ownerName,ownerEmail,ownerPassword})}catch{}}
  if(registering)return <main className="onboarding-screen"><aside className="onboarding-brand"><img src="/syntra/logo-wordmark-dark.png" alt="Syntra Software"/><div><p>CONFIGURA TU ESPACIO</p><h1>Tu estacionamiento listo para operar.</h1><span>Registra tu empresa, primera sucursal y cuenta propietaria en tres pasos.</span></div><nav>{[[1,"Empresa"],[2,"Sucursal"],[3,"Propietario"]].map(([n,label])=><div key={n} className={step>=Number(n)?"active":""}><i>{step>Number(n)?"✓":n}</i><b>{label}</b></div>)}</nav><small>SYNTRA PARKFLOW · GESTIÓN PROFESIONAL</small></aside><section className="onboarding-form"><button className="onboarding-back" onClick={back}>← {step===1?"Volver al acceso":"Anterior"}</button><form onSubmit={create}><p className="eyebrow">PASO {step} DE 3</p>{step===1&&<><h2>Cuéntanos sobre tu empresa</h2><p className="onboarding-copy">Esta información identificará tu cuenta y aparecerá en la operación del estacionamiento.</p><label>Nombre comercial<input autoFocus value={name} onChange={e=>{const value=e.target.value;setName(value);setSlug(value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,""))}} placeholder="Ej. Estacionamientos del Centro" required/></label><label>Identificador del sistema<input value={slug} onChange={e=>setSlug(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g,""))} placeholder="estacionamientos-del-centro" required/><small>Se genera automáticamente y puedes ajustarlo.</small></label></>}{step===2&&<><h2>Configura tu primera sucursal</h2><p className="onboarding-copy">Podrás agregar nuevas ubicaciones cuando ingreses al sistema.</p><div className="form-grid"><label>Nombre de sucursal<input autoFocus value={lotName} onChange={e=>setLotName(e.target.value)} placeholder="Sucursal principal" required/></label><label>Código<input value={lotCode} onChange={e=>setLotCode(e.target.value.toUpperCase())} maxLength={8} placeholder="MATRIZ" required/></label></div><label>Capacidad total<input type="number" min={1} value={capacity} onChange={e=>setCapacity(Number(e.target.value))} required/><small>Número de cajones disponibles en esta ubicación.</small></label></>}{step===3&&<><h2>Crea tu cuenta propietaria</h2><p className="onboarding-copy">Tendrás control completo de sucursales, tarifas, usuarios y reportes.</p><div className="form-grid"><label>Nombre completo<input autoFocus value={ownerName} onChange={e=>setOwnerName(e.target.value)} autoComplete="name" placeholder="Tu nombre" required/></label><label>Correo electrónico<input type="email" value={ownerEmail} onChange={e=>setOwnerEmail(e.target.value)} autoComplete="email" placeholder="propietario@empresa.com" required/></label><label>Contraseña<input type="password" value={ownerPassword} onChange={e=>setOwnerPassword(e.target.value)} minLength={8} autoComplete="new-password" placeholder="Mínimo 8 caracteres" required/></label><label>Confirmar contraseña<input type="password" value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} minLength={8} autoComplete="new-password" placeholder="Repite la contraseña" required/></label></div><div className="creation-summary"><CheckCircle2/><p>La cuenta quedará activa inmediatamente. No se enviarán enlaces mágicos.</p></div></>}{(formError||error)&&<div className="onboarding-error">{formError||error}</div>}<footer>{step<3?<button type="button" className="primary full" onClick={next}>Continuar <ChevronRight size={17}/></button>:<button className="primary full" disabled={saving}>{saving?"Creando tu empresa…":"Crear empresa y comenzar"}</button>}<small>Al continuar aceptas los términos de servicio y el aviso de privacidad.</small></footer></form></section></main>;
  return <main className="syntra-login"><section className="syntra-login-content"><img src="/syntra/logo-wordmark-dark.png" alt="Syntra Software" className="syntra-login-logo"/><p className="syntra-login-subtitle">Control profesional para estacionamientos</p><form onSubmit={onLogin}><input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="Correo electrónico" autoCapitalize="none" autoComplete="email" required/><input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="••••••••" minLength={8} autoComplete="current-password" required/>{error&&<div className="syntra-login-error">{error}</div>}<button className="syntra-enter" type="submit" disabled={saving}>{saving?"Verificando…":"Entrar"}</button></form><button className="syntra-forgot" onClick={()=>setForgot(v=>!v)}>¿Olvidaste tu contraseña?</button>{forgot&&<div className="syntra-help">Solicita al propietario de tu negocio que restablezca tu acceso desde Personal y permisos.</div>}<div className="syntra-register"><div><span/><b>¿Es tu primera vez?</b><span/></div><button onClick={()=>{setRegistering(true);setStep(1)}}>Crear una empresa</button></div><button className="syntra-demo" onClick={onDemo}>Explorar en modo demostración</button></section></main>
}
function roleLabel(role:string){return({super_admin:"Super administrador",owner:"Dueño del negocio",admin:"Administrador",cashier:"Cajero",operator:"Operador",viewer:"Consulta"} as Record<string,string>)[role]??role}
